-- 098: treinamento obrigatório só para os NOVOS colaboradores (admitidos a partir de uma data).
-- Usado pelo treinamento de boas-vindas (norteadores + Regulamento Interno), que este arquivo
-- já cria (gerado de src/components/Educacao/treinamentoBoasVindas.ts). Vale também para
-- qualquer treinamento: "Quem precisa fazer" → "Só os novos colaboradores, admitidos a partir de".
-- Rodar no dev e na produção ANTES de publicar.

alter table treinamentos add column if not exists admitidos_desde date;


-- Treinamento de boas-vindas (norteadores + Regulamento Interno), já disponível em DP → Educação.
-- Obrigatório só para quem for admitido a partir de 03/11/2026, prazo de 7 dias.
-- Se já existir (rodou de novo), não muda nada.
insert into treinamentos (id, titulo, descricao, carga_horaria_min, conteudos, prova, obrigatorio_todos, obrigatorio_cargos, obrigatorio_setores, admitidos_desde, prazo_dias, ativo, criado_por, criado_em, atualizado_em)
values (
  'trein-boas-vindas',
  'Boas-vindas à JMT — Norteadores e Regulamento Interno',
  'Integração de novos colaboradores: quem somos, propósito, missão, visão, valores, pilares e o Regulamento Interno (jornada, ponto, conduta, uniforme e EPI, medidas disciplinares, direitos e deveres).',
  40,
  $bv$[{"id":"bv-cont-1","tipo":"texto","titulo":"Seja bem-vindo(a)! Quem somos","texto":"Que bom ter você com a gente! A Jobson de Moraes Transportes Ltda (JMT) faz logística de produtos para a saúde: medicamentos, vacinas, materiais hospitalares e cargas que não podem esperar, esquentar nem se perder.\n\nNossa assinatura resume o nosso jeito de trabalhar: *Segurança, Rastreabilidade e Pontualidade na Logística da Saúde*.\n\nNeste treinamento você conhece os nossos norteadores — o que guia as decisões da empresa — e o Regulamento Interno, com as regras do dia a dia. No fim tem uma provinha rápida. Leia com calma: ele é a base para tudo o que vem depois.","telas":[{"titulo":"Boas-vindas","imagem":"/treinamento-boas-vindas/bv-1-boas-vindas.png","marcas":[]}]},{"id":"bv-cont-2","tipo":"texto","titulo":"Norteadores: propósito, missão e visão","texto":"*Propósito — Por que existimos:* Levar saúde com segurança, do remetente ao destino final.\nCada caixa que passa pela sua mão pode ser o remédio de alguém. É por isso que fazemos tudo com tanto cuidado.\n\n*Missão — O que fazemos, hoje:* Entregar soluções de logística para produtos de saúde, garantindo segurança, conformidade, rastreabilidade e pontualidade, com processos padronizados e gestão por indicadores.\nNa prática: seguir os procedimentos (POPs e Instruções de Trabalho), registrar tudo certinho e cumprir os horários.\n\n*Visão — Onde queremos chegar:* Ser reconhecida pela excelência em logística de produtos para a saúde, garantindo entregas seguras, rastreáveis e pontuais onde quer que atuemos.\nA reputação da JMT é construída em cada entrega — inclusive na sua.","telas":[{"titulo":"Propósito, missão e visão","imagem":"/treinamento-boas-vindas/bv-2-norteadores.png","marcas":[]}]},{"id":"bv-cont-3","tipo":"texto","titulo":"Nossos valores","texto":"• Ética e transparência: Conduta íntegra em todas as relações — com clientes, colaboradores e parceiros.\n• Qualidade e segurança: Rigor operacional e conformidade regulatória em cada etapa da cadeia logística.\n• Foco no cliente: Soluções desenhadas a partir da necessidade real de quem confia sua carga à JMT.\n• Comunicação e respeito: Relações claras, diretas e respeitosas em todos os níveis da organização.\n• Autonomia com responsabilidade: Liberdade para decidir e agir, com responsabilidade pelo resultado.\n• Melhoria contínua e inovação: Evolução constante de processos, tecnologia e padrões de atendimento.\n\nUm exemplo: se você perceber uma caixa avariada ou um problema de temperatura, avise na hora — isso é ética, qualidade e foco no cliente ao mesmo tempo. E se tiver uma ideia para melhorar algo, mande pelo app em Sugestões: é melhoria contínua.","telas":[{"titulo":"Os 6 valores","imagem":"/treinamento-boas-vindas/bv-3-valores.png","marcas":[]}]},{"id":"bv-cont-4","tipo":"texto","titulo":"Os 4 pilares de cada entrega","texto":"• Segurança: Proteção da integridade de cargas farmacêuticas e pessoas.\n• Rastreabilidade: Visibilidade de temperatura e localização de ponta a ponta.\n• Pontualidade: Compromisso com prazos críticos em saídas e entregas.\n• Conformidade ANVISA/BPAD: Rigor regulatório de acordo com a RDC 430/2020 e Boas Práticas.\n\nTrabalhamos com produtos para a saúde, então seguimos as regras da ANVISA (RDC 430/2020 — Boas Práticas de Armazenagem, Distribuição e Transporte). Por isso existem controles de temperatura, registros e conferências: eles protegem o produto e o paciente.","telas":[{"titulo":"Pilares operacionais","imagem":"/treinamento-boas-vindas/bv-4-pilares.png","marcas":[]}]},{"id":"bv-cont-5","tipo":"texto","titulo":"Regulamento Interno — objetivo","texto":"O Regulamento Interno (Revisão de outubro de 2026) reúne as regras de convivência e de trabalho da JMT. A seguir estão os pontos principais; o texto completo fica no seu link pessoal, em Mais → Regulamento, onde você também assina a ciência.\n\nEste Regulamento tem a finalidade de nortear a conduta dos colaboradores da JOBSON DE MORAES TRANSPORTES LTDA no dia a dia de trabalho, visando assegurar a ordem, a segurança, a produtividade e a harmonia no ambiente de trabalho.\n\nAs regras aqui descritas complementam o contrato de trabalho e não substituem nem reduzem os direitos garantidos pela Consolidação das Leis do Trabalho (CLT), pela legislação aplicável e pela convenção coletiva da categoria. Em caso de conflito, prevalece a norma mais favorável ao colaborador."},{"id":"bv-cont-6","tipo":"texto","titulo":"Jornada de trabalho e ponto","texto":"A jornada de trabalho varia conforme a operação:\n\n• Farma Rodoviário (motoristas e ajudantes): 06h00–11h00 / 12h12–16h00 (Terça a sábado)\n• Farma Aéreo (motoristas e ajudantes): 08h00–12h00 / 13h12–18h00 (Segunda a sexta)\n• Farma Aéreo e Rodoviário (escritórios): 08h00–12h00 / 13h12–18h00 (Segunda a sexta)\n• Qualidade (responsável técnica): 08h00–12h00 / 13h12–18h00 (Segunda a sexta)\n• ASG: 07h00–11h00 / 12h12–17h00 (Segunda a sexta)\n• Recebimento e expedição (noturno): 20h00–00h00 / 01h12–05h10 (Segunda a sexta)\n• Transbordo (Natal x Mossoró): 00h00–04h00 / 05h00–12h00 (Terça a sexta)\n• Operação Unimed: 10h00–14h00 / 15h12–20h00 (Segunda a sexta)\n\nÉ dever do colaborador cumprir a sua jornada com pontualidade e assiduidade, registrando a entrada, a saída e os intervalos no ponto eletrônico disponibilizado pela empresa.\n\nO intervalo para repouso e alimentação é obrigatório e deve ser efetivamente usufruído (CLT, art. 71). O trabalho entre 22h00 e 05h00 é noturno e observa a hora noturna reduzida e o adicional noturno previstos no art. 73 da CLT.\n\nAs horas extras são pagas ou compensadas na forma da lei e da convenção coletiva. Não são descontadas nem computadas como hora extra as variações de registro de até 5 minutos, observado o limite de 10 minutos diários (CLT, art. 58, § 1º).\n\n*Condutas que podem levar a advertências ou penalidades:*\n\n• Atrasos reincidentes acima dos 15 minutos de tolerância da empresa, em mais de 3 dias no mesmo mês (advertência, seguindo a gradação do item 7).\n• Faltas não justificadas, isto é, sem comunicação e sem atestado (desconto em folha do dia e, quando for o caso, do descanso semanal remunerado — Lei nº 605/1949).\n• Não informar o agendamento de consulta ou exame médico com, no mínimo, 2 dias de antecedência (advertência, seguindo a gradação do item 7).\n\nImportante: Não são consideradas faltas as ausências permitidas por lei (CLT, art. 473 — por exemplo, falecimento de familiar, casamento, nascimento de filho, doação de sangue, alistamento eleitoral e comparecimento a juízo) nem as justificadas por atestado médico válido, que deve ser entregue ao Departamento Pessoal.","telas":[{"titulo":"As 4 marcações do ponto","imagem":"/treinamento-boas-vindas/bv-5-ponto.png","marcas":[]}]},{"id":"bv-cont-7","tipo":"texto","titulo":"Conduta e comportamento","texto":"Os colaboradores devem agir com ética e respeito com gestores, colegas, clientes e parceiros, observando os valores da empresa.\n\nSão proibidos: assédio moral ou sexual, qualquer forma de discriminação, violência verbal ou física, e o uso, porte ou estar sob efeito de bebida alcoólica ou substâncias ilícitas no ambiente de trabalho ou em serviço. Situações de assédio ou violência devem ser comunicadas ao supervisor ou ao Departamento Pessoal, que tratarão o caso com sigilo, sem qualquer retaliação a quem comunicar (Lei nº 14.457/2022).\n\nImportante: O uso do celular e das redes sociais durante o trabalho deve ser mínimo, para não prejudicar o rendimento das atividades. Para motoristas, é proibido usar o celular com o veículo em movimento (Código de Trânsito Brasileiro, art. 252).","telas":[{"titulo":"Tolerância zero","imagem":"/treinamento-boas-vindas/bv-7-conduta.png","marcas":[]}]},{"id":"bv-cont-8","tipo":"texto","titulo":"Uniforme, EPI e segurança do trabalho","texto":"*Motoristas e ajudantes:*\n\n• Camisa;\n• Calça jeans ou preta;\n• Cinta (opcional);\n• Bota;\n• Crachá.\n\n*Escritórios:*\n\n• Camisa;\n• Calça jeans ou preta;\n• Sapato fechado;\n• Crachá.\n\n*ASG:*\n\n• Camisa;\n• Calça legging preta;\n• Bota;\n• Crachá.\n\n*Recebimento e expedição (noturno):*\n\n• Camisa;\n• Bermuda jeans ou preta;\n• Cinta (opcional);\n• Bota;\n• Crachá.\n\nÉ obrigatório usar os itens acima durante toda a jornada e manter higiene pessoal adequada ao ambiente de trabalho. Os EPIs são fornecidos gratuitamente pela empresa (CLT, art. 166; NR-6), e cabe ao colaborador usá-los, conservá-los e comunicar perda ou dano. A não utilização pode acarretar medidas disciplinares.\n\n• Utilizar de forma adequada e constante os EPIs disponibilizados. A recusa injustificada ao uso de EPI constitui ato faltoso (CLT, art. 158, parágrafo único).\n• Motoristas: dirigir com atenção e dentro da lei — velocidade controlada, sem bebida alcoólica ou drogas — e cumprir os deveres do motorista profissional (CLT, art. 235-B), inclusive o respeito aos tempos de direção e descanso e os exames toxicológicos exigidos por lei.\n\n*O descumprimento dessas medidas pode resultar em:*\n\n• Não utilização dos EPIs: aplicação de advertência, seguindo a gradação do item 7.\n• Multas de trânsito: cada caso é analisado. Comprovada a responsabilidade do colaborador, o valor pode ser descontado em folha, nos limites do art. 462, § 1º, da CLT (dano causado com dolo ou, havendo acordo prévio, por culpa).","telas":[{"titulo":"Uniforme por função","imagem":"/treinamento-boas-vindas/bv-6-uniforme.png","marcas":[]}]},{"id":"bv-cont-9","tipo":"texto","titulo":"Bens e recursos da empresa","texto":"Veículos: os veículos da empresa devem ser utilizados exclusivamente em atividades de interesse da empresa, não sendo permitido o uso para fins particulares.\n\nEquipamentos do escritório: computadores, telefones, móveis e materiais de papelaria devem ser usados exclusivamente nas atividades da empresa, de maneira consciente, evitando constrangimentos e desperdícios.\n\nAmbientes e equipamentos de uso comum: os colaboradores devem zelar pela conservação das áreas comuns e dos equipamentos disponibilizados (ex.: copa e utensílios, sala de descanso, ar-condicionado).\n\nImportante: Descuido com o patrimônio da empresa pode resultar em advertência. Desconto por dano só ocorre nos casos permitidos pelo art. 462, § 1º, da CLT."},{"id":"bv-cont-10","tipo":"texto","titulo":"Penalidades e advertências","texto":"O descumprimento das normas deste Regulamento pode levar às seguintes medidas disciplinares: advertência (verbal ou escrita), suspensão (de 1, 3 ou 5 dias) ou dispensa por justa causa, nas hipóteses do art. 482 da CLT.\n\n*Na aplicação das medidas, a empresa observa:*\n\n• Gradação: em regra, advertência verbal, advertência escrita, nova advertência escrita, suspensão de 1 dia, suspensão de 3 dias, suspensão de 5 dias e, por último, justa causa. Faltas graves podem justificar medida mais severa desde o início.\n• Proporcionalidade: a medida deve ser compatível com a gravidade da falta.\n• Imediatidade: a medida é aplicada logo após a empresa tomar conhecimento da falta.\n• Uma única punição por fato: a mesma falta não é punida duas vezes.\n• Reincidência: são consideradas as medidas aplicadas nos últimos 12 meses.\n• A suspensão não pode passar de 30 dias consecutivos (CLT, art. 474). Os dias de suspensão não são remunerados.\n\nResponsáveis: os supervisores propõem a medida, e o RH/Departamento Pessoal analisa e aplica. O colaborador recebe o documento para ciência — a assinatura indica que tomou conhecimento, e não que concorda. Se o colaborador se recusar a assinar, a ciência é registrada por duas testemunhas.","telas":[{"titulo":"A gradação das medidas","imagem":"/treinamento-boas-vindas/bv-8-disciplinar.png","marcas":[]}]},{"id":"bv-cont-11","tipo":"texto","titulo":"Direitos e deveres","texto":"Benefícios: vale-transporte (Lei nº 7.418/1985, com desconto de até 6% do salário-base), vale-alimentação e crescimento de carreira, de acordo com a demanda interna. Estes benefícios se somam aos direitos previstos na CLT e na convenção coletiva da categoria.\n\nDeveres: cumprir este Regulamento; manter sigilo sobre informações da empresa, dos clientes e das cargas, inclusive dados pessoais a que tiver acesso, que só podem ser usados para o trabalho (Lei Geral de Proteção de Dados, Lei nº 13.709/2018); e manter a produtividade.\n\nAo tomar conhecimento deste Regulamento, o colaborador fica ciente dos seus direitos, deveres e das sanções aplicáveis em caso de descumprimento das normas.\n\nEste Regulamento entra em vigor na data de sua divulgação. Alterações serão comunicadas a todos os colaboradores, e mudanças que retirem vantagens só se aplicam a quem for admitido depois delas (Súmula 51 do TST)."},{"id":"bv-cont-12","tipo":"texto","titulo":"Seus próximos passos","texto":"1. Faça a provinha deste treinamento (nota mínima 70).\n2. No seu link pessoal, abra Mais → Regulamento, leia a versão completa e assine a ciência.\n3. Instale o app JMT Colaborador e toque em \"Ativar avisos\" — você recebe o lembrete do ponto, comunicados e documentos.\n4. Bata o ponto pelo app nas 4 marcações do dia.\n5. Dúvidas sobre salário, férias, benefícios ou documentos: use o \"Fale com o DP\".\n6. Viu algo errado na operação (avaria, temperatura, embalagem)? Use \"Relatar ocorrência\". Tem uma ideia? Mande em \"Sugestões\".\n\nSeja bem-vindo(a) ao time. Conte com a gente!"}]$bv$::jsonb,
  $bv${"notaMinima":70,"perguntas":[{"id":"bv-p1","enunciado":"Qual é o propósito da JMT (por que existimos)?","alternativas":["Levar saúde com segurança, do remetente ao destino final.","Ser a transportadora mais barata da região.","Entregar qualquer tipo de carga no menor tempo possível."],"correta":0},{"id":"bv-p2","enunciado":"Quais são os 4 pilares operacionais de cada entrega?","alternativas":["Velocidade, preço, volume e lucro.","Segurança, rastreabilidade, pontualidade e conformidade ANVISA/BPAD.","Uniforme, crachá, bota e EPI."],"correta":1},{"id":"bv-p3","enunciado":"Qual destes é um valor da JMT?","alternativas":["Autonomia com responsabilidade.","Resultado a qualquer custo.","Cada um por si."],"correta":0},{"id":"bv-p4","enunciado":"Quantas vezes por dia você registra o ponto numa jornada com intervalo?","alternativas":["Só na entrada.","Na entrada e na saída.","4 vezes: entrada, saída para o intervalo, volta do intervalo e saída."],"correta":2},{"id":"bv-p5","enunciado":"Você tem uma consulta médica agendada. O que o Regulamento pede?","alternativas":["Avisar com pelo menos 2 dias de antecedência e entregar o atestado ao DP.","Faltar e explicar só quando voltar.","Não precisa avisar ninguém."],"correta":0},{"id":"bv-p6","enunciado":"Sobre os EPIs, é correto dizer que:","alternativas":["O colaborador compra os próprios EPIs.","São fornecidos gratuitamente pela empresa e o uso é obrigatório; recusar sem motivo é falta.","Só precisam ser usados quando o supervisor está olhando."],"correta":1},{"id":"bv-p7","enunciado":"Você presenciou um caso de assédio. O que fazer?","alternativas":["Não se envolver.","Postar nas redes sociais.","Comunicar ao supervisor ou ao DP, que tratam com sigilo e sem retaliação a quem comunicou."],"correta":2},{"id":"bv-p8","enunciado":"Assinar a ciência de uma medida disciplinar significa:","alternativas":["Que você concorda com a medida.","Que você tomou conhecimento dela — não que concorda.","Que você abre mão dos seus direitos."],"correta":1},{"id":"bv-p9","enunciado":"Dados de clientes, cargas e colegas a que você tem acesso no trabalho:","alternativas":["Podem ser compartilhados com amigos.","Só podem ser usados para o trabalho e devem ser mantidos em sigilo (LGPD).","Podem ser postados se não tiver o nome."],"correta":1},{"id":"bv-p10","enunciado":"Motorista dirigindo o veículo da empresa pode usar o celular?","alternativas":["Sim, se for rápido.","Não com o veículo em movimento (CTB, art. 252).","Sim, só para mensagens de voz."],"correta":1}]}$bv$::jsonb,
  true, '{}', '{}', '2026-11-03', 7, true, 'Departamento Pessoal', now(), now()
)
on conflict (id) do nothing;

notify pgrst, 'reload schema';
